{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In humans, [18F]-4-FDEX, a piperidine-containing radiotracer, showed good initial brain entry (~4.2%ID at 5 min), demonstrating that this scaffold class achieves meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Praziquantel, an amide-containing CNS drug, reached 5.7 µg/g brain after IV dosing in rats, providing direct quantitative evidence that amide-bearing molecules in this transfer range cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "AD-8007, a diphenyl-substituted amide with a cyclic amine, was detected at significantly higher levels in mouse brain than a comparator, directly confirming brain penetration for a close structural relative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A fluorinated nornicotine analogue showed high, rapid striatal uptake in rat PET, supporting CNS access for small basic amine-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A piperazine-containing PET ligand showed high radioactivity uptake in cat cortex, thalamus, striatum, and cerebellum, confirming robust BBB penetration for a related basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "N-(N-benzylpiperidin-4-yl)-2-[18F]fluorobenzamide showed good mouse brain uptake, supporting the piperidine-amide class as CNS penetrant.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence points to meaningful CNS access: multiple piperidine/amide and diphenyl-containing molecules show high brain uptake in rodents, cats, monkeys, and humans. The query shares the key ionizable amine, aromatic, and amide features, so the prediction is pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query molecule itself.",
    "No explicit P-gp/BCRP efflux data for the query; efflux liability cannot be fully excluded.",
    "The chroman-ethyl substituent is not directly represented in the closest analogues, so its effect on CNS exposure is inferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

